mapper.select:
SELECT b.TOUR_ID, b.TOUR_NM, c1.CMM_CM_NM AS SIDO_NM, c2.CMM_CM_NM AS SGG_NM, b.ROAD_ADDR, b.DETAIL_ADDR, b.ZIP_CD, d.CATE_CD, d.CATE_NM, IFNULL(a.AVG_SCORE,0) AS AVG_SCORE, b.FIRST_IMAGE, b.TOUR_NM_EN, b.TOUR_NM_JA FROM TB_TRMA_TOUR_LIST b LEFT JOIN ( SELECT TOUR_ID, AVG(REVIEW_SCORE) AS AVG_SCORE FROM TB_TRMA_MOIM_REVIEW GROUP BY TOUR_ID ) a ON b.TOUR_ID = a.TOUR_ID LEFT JOIN ( SELECT tc.TOUR_ID, GROUP_CONCAT(tc.CATE_CD ORDER BY tc.CATE_CD) AS CATE_CD, GROUP_CONCAT(cd.CMM_CM_NM ORDER BY cd.CMM_CM_NM) AS CATE_NM FROM TB_TRMA_TOUR_CATE tc LEFT JOIN TB_TRMA_CMM_CD_D cd ON tc.CATE_CD = cd.CMM_CDV AND cd.CMM_CD_ID = 'TOUR_LCLS_CD' GROUP BY tc.TOUR_ID ) d ON b.TOUR_ID = d.TOUR_ID LEFT JOIN TB_TRMA_CMM_CD_D c1 ON CONCAT(b.SIDO_CD,'00000000') = c1.CMM_CDV AND c1.CMM_CD_ID = 'SIDO_CD' LEFT JOIN TB_TRMA_CMM_CD_D c2 ON CONCAT(b.SIDO_CD,b.SGG_CD,'00000') = c2.CMM_CDV AND c2.CMM_CD_ID = 'SGG_CD' WHERE b.USE_YN='Y'
AND ( b.TOUR_NM LIKE CONCAT('%', #{keyword}, '%') OR b.TOUR_CONTENT LIKE CONCAT('%', #{keyword}, '%') OR b.ROAD_ADDR LIKE CONCAT('%', #{keyword}, '%') OR c1.CMM_CM_NM LIKE CONCAT('%', #{keyword}, '%') OR c2.CMM_CM_NM LIKE CONCAT('%', #{keyword}, '%') )
AND d.CATE_CD = #{cateCd}
ORDER BY AVG_SCORE DESC LIMIT 10 OFFSET #{offset}

mapper.update:
UPDATE TB_TRMA_TOUR_LIST
TOUR_NM_EN = #{tourNmEn}, TOUR_NM_JA = #{tourNmJa}, TOUR_CONTENT_EN = #{overviewEn}, TOUR_CONTENT_JA = #{overviewJa},
WHERE TOUR_ID = #{tourId}
